import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { prepareVoiceFoundryHandoff } from './fallen-voice-foundry-handoff.mjs';

/** Works with the file already generated by existing Fallen Studio compiler. */
export function writeVoiceFoundryQueue(draftFile, outputDir) {
  const bundle=JSON.parse(fs.readFileSync(path.resolve(draftFile),'utf8'));
  const {foundry,cues,receipt}=prepareVoiceFoundryHandoff(bundle);
  const dest=path.resolve(outputDir);
  fs.mkdirSync(dest,{recursive:true});
  for (const [filename,record] of [
    ['voice-foundry-session.held.json',foundry],
    ['voice-cue-timing.held.json',cues],
    ['voice-handoff-receipt.json',receipt]
  ]) fs.writeFileSync(path.join(dest,filename),JSON.stringify(record,null,2)+'\n','utf8');
  return receipt;
}

if (process.argv[1]&&path.resolve(process.argv[1])===fileURLToPath(import.meta.url)){
  try {
    const [draft,output,...extra]=process.argv.slice(2);
    if(!draft||!output||extra.length)throw Error('Usage: node systemia/graphics-command/write-voice-foundry-queue.mjs <fallen-studio-draft.json> <output-dir>');
    console.log(JSON.stringify(writeVoiceFoundryQueue(draft,output),null,2));
  } catch(error){console.error(error);process.exitCode=1;}
}
